mapper.select:
SELECT 
FROM ai_generation
WHERE org_id = #{orgId}
  AND operator_account_id = #{operatorAccountId}
  AND request_key = #{requestKey}

SELECT COUNT(*)
FROM ai_generation
WHERE org_id = #{orgId}
  AND created_at >= #{since}

mapper.update:
UPDATE ai_generation
SET status = 'FAILED',
    error_code = #{errorCode}
WHERE org_id = #{orgId}
  AND status = 'RUNNING'
  AND created_at < #{before}

mapper.select:
SELECT 
FROM ai_generation
WHERE activity_id = #{activityId}
  AND type = #{type}
ORDER BY id DESC
LIMIT #{limit}
